import 'fake-indexeddb/auto';
import {it,expect,afterEach} from 'vitest';
import {readFileSync,writeFileSync,existsSync} from 'node:fs';
import type {ProjectData} from '../src/domain/types';
import {ScenarioStore,type FaultStage} from '../src/storage/store';
import {createProject,createEntity,newId,textToRichText,validateProject} from '../src/domain/model';
import {nativeDocuments} from '../src/sync/nativeBridge';
import {ContractSyncServer} from '../src/sync/testing';
import {valueHash,createSyncOperation,type SyncSession,type SyncAck} from '../src/sync/protocol';
import {DedicatedSupabaseClient} from '../src/sync/supabaseClient';
const root='/tmp/shinariokanri-independent-rb09-73a279a/independent',stores:ScenarioStore[]=[],names=new WeakMap<ScenarioStore,string>();
const inputPath=root+'/fixtures/native-two-targets.json';
function input():{p:ProjectData;account:string;idA:string;idB:string}{if(!existsSync(inputPath)){const p=createProject('独立同期：共通元と後発編集'),a=createEntity(p.projectId,'note','共通A',{body:textToRichText('😀Aの共通本文')}),b=createEntity(p.projectId,'note','共通B',{body:textToRichText('😀Bの共通本文')});a.status=b.status='confirmed';a.visibility=b.visibility='team';p.entities.push(a,b);writeFileSync(inputPath,JSON.stringify({p,account:newId(),idA:a.id,idB:b.id},null,2)+'\n');}return JSON.parse(readFileSync(inputPath,'utf8'));}
function open(account:string,fault?:(s:FaultStage)=>void){const databaseName='independent-sync-'+newId(),s=new ScenarioStore({accountId:account,databaseName,faultInjector:fault});names.set(s,databaseName);stores.push(s);return s;}
function reopen(s:ScenarioStore,account:string){const n=names.get(s)!;s.close();const next=new ScenarioStore({accountId:account,databaseName:n});names.set(next,n);stores.push(next);return next;}
afterEach(async()=>{for(const s of stores.splice(0))await s.deleteDatabase();});
function proof(id:string,value:unknown){writeFileSync(root+'/fixtures/'+id+'.json',JSON.stringify(value,null,2)+'\n');}
async function seed(fault?:(s:FaultStage)=>void){const f=input(),a=open(f.account,fault),b=open(f.account),pA=(await a.saveProject(f.p,{reason:'独立Aの初期保存'})).project,pB=(await b.saveProject(f.p,{reason:'独立Bの初期保存'})).project,documents=nativeDocuments(pA,'1'),server=new ContractSyncServer(),session:SyncSession={accountId:f.account,authenticated:true,generation:newId()};server.seed({projectId:f.p.projectId,revision:'1',documents,members:{[f.account]:'owner'}});for(const [s,p]of [[a,pA],[b,pB]] as const)await s.bindConfirmedProject({projectId:p.projectId,localRevision:p.revision,serverRevision:'1',documents,contentHash:await valueHash(documents),outboxIds:(await s.listOutbox(p.projectId)).map(x=>x.operationId)});return{...f,a,b,server,session,projectId:f.p.projectId};}
async function edit(s:ScenarioStore,pid:string,id:string,name?:string,body?:string){const p=(await s.getProject(pid))!,e=p.entities.find(e=>e.id===id)!;if(name!==undefined)e.name=name;if(body!==undefined&&e.kind==='note')e.data.body=textToRichText(body);return(await s.saveProject(p,{reason:'独立通常保存'})).project;}
async function send(s:ScenarioStore,f:Awaited<ReturnType<typeof seed>>){const operation=(await s.prepareSavedOperations(f.projectId))!;const ack=await f.server.send(operation,f.session);await s.commitPreparedAck(f.projectId,ack);return{operation,ack};}
async function conflict(){const f=await seed();await edit(f.a,f.projectId,f.idA,'サーバーA');await send(f.a,f);await edit(f.b,f.projectId,f.idA,'端末B');await send(f.b,f);return{...f,row:(await f.b.listSyncConflictAlternatives(f.projectId))[0]};}
it('R9V01 actual saved operations use confirmed server base after two dependent local revisions, and cold retry is identical',async()=>{const f=await seed();expect(validateProject(f.p).ok).toBe(true);await edit(f.a,f.projectId,f.idA,'一稿');await edit(f.a,f.projectId,f.idA,'二稿');const operation=(await f.a.prepareSavedOperations(f.projectId))!;expect(operation.baseRevision).toBe('1');expect(operation.targets.find(t=>t.targetId===f.idA)?.base?.fields.name).toBe('共通A');expect(operation.targets.find(t=>t.targetId===f.idA)?.local.fields.name).toBe('二稿');f.a=reopen(f.a,f.account);expect(await f.a.prepareSavedOperations(f.projectId)).toEqual(operation);const ack=await f.server.send(operation,f.session);await f.a.commitPreparedAck(f.projectId,ack);expect(await f.a.listOutbox(f.projectId)).toHaveLength(0);expect(await f.a.listSyncAckEvidence(f.projectId)).toHaveLength(1);proof('R9V01',{operation,ack,saveState:await f.a.getSaveState(f.projectId)});});
it('R9V02 unrelated remote target enters confirmed native image while later local edits stay pending and rebase',async()=>{const f=await seed();await edit(f.a,f.projectId,f.idA,'送信A');const op=(await f.a.prepareSavedOperations(f.projectId))!;await edit(f.b,f.projectId,f.idB,'遠隔B');await send(f.b,f);const ack=await f.server.send(op,f.session);await edit(f.a,f.projectId,f.idA,'後発A');await f.a.commitPreparedAck(f.projectId,ack);const p=(await f.a.getProject(f.projectId))!;expect(p.entities.find(e=>e.id===f.idA)?.name).toBe('後発A');expect(p.entities.find(e=>e.id===f.idB)?.name).toBe('遠隔B');expect(await f.a.listOutbox(f.projectId)).toHaveLength(1);const next=(await f.a.prepareSavedOperations(f.projectId))!;expect(next.baseRevision).toBe('3');expect(next.targets.find(t=>t.targetId===f.idA)?.base?.fields.name).toBe('送信A');proof('R9V02',{ack,next});});
it('R9D01 post-ACK conflict on a target outside the original prepared operation remains selected and enters the resolution command',async()=>{const f=await seed();await edit(f.a,f.projectId,f.idA,'送信A');const operation=(await f.a.prepareSavedOperations(f.projectId))!;await edit(f.b,f.projectId,f.idB,'遠隔B');await send(f.b,f);const ack=await f.server.send(operation,f.session);await edit(f.a,f.projectId,f.idB,'通信中の端末B');await f.a.commitPreparedAck(f.projectId,ack);const row=(await f.a.listSyncConflictAlternatives(f.projectId))[0];expect(row.conflicts.map(c=>c.targetId)).toContain(f.idB);const plan=await f.a.previewSyncResolution(f.projectId,row.operationId,{[f.idB]:{strategy:'local'}});proof('R9D01',{originalTargets:operation.targets.map(t=>t.targetId),row,plan});expect(plan.operation.targets.map(t=>t.targetId)).toContain(f.idB);expect(plan.candidate.entities.find(e=>e.id===f.idB)?.name).toBe('通信中の端末B');});
it('R9D02 preview captures choices before the first await, later caller changes do not reverse the submitted selection',async()=>{const f=await conflict(),choices:any={[f.idA]:{strategy:'server'}},pending=f.b.previewSyncResolution(f.projectId,f.row.operationId,choices);choices[f.idA].strategy='local';const plan=await pending;proof('R9D02',{submittedStrategy:'server',callerLater:choices,plan});expect(plan.choices[f.idA]).toEqual({strategy:'server'});expect(plan.candidate.entities.find(e=>e.id===f.idA)?.name).toBe('サーバーA');});
it('R9D03 reconfirmed field resolution keeps independent edits made after conflict capture before the new preview',async()=>{const f=await conflict();await edit(f.b,f.projectId,f.idA,undefined,'競合後に書いた独立本文😀');const plan=await f.b.previewSyncResolution(f.projectId,f.row.operationId,{[f.idA]:{strategy:'fields',choices:{name:'server'}}});proof('R9D03',{row:f.row,plan});expect(plan.candidate.entities.find(e=>e.id===f.idA)?.data).toMatchObject({body:[{text:'競合後に書いた独立本文😀'}]});});
it('R9V03 failed conflict ACK transaction preserves every rejected target and original alternatives; identical retry is durable and duplicate ACK cannot change it',async()=>{let fail=false;const f=await seed(stage=>{if(fail&&stage==='before-commit')throw new DOMException('fixture quota','QuotaExceededError');});await edit(f.b,f.projectId,f.idA,'遠隔A');await send(f.b,f);const p=(await f.a.getProject(f.projectId))!;p.entities.find(e=>e.id===f.idA)!.name='端末A';p.entities.find(e=>e.id===f.idB)!.name='未適用B';await f.a.saveProject(p,{reason:'原子二対象'});const operation=(await f.a.prepareSavedOperations(f.projectId))!,ack=await f.server.send(operation,f.session),before=await f.a.getProject(f.projectId);expect(ack.status).toBe('conflict');expect(f.server.readForTest(f.projectId).documents.find(d=>d.id===f.idB)?.fields.name).toBe('共通B');fail=true;await expect(f.a.commitPreparedAck(f.projectId,ack)).rejects.toThrow();expect(await f.a.getProject(f.projectId)).toEqual(before);expect(await f.a.listPreparedOperations(f.projectId)).toHaveLength(1);expect(await f.a.listSyncAckEvidence(f.projectId)).toHaveLength(0);fail=false;await f.a.commitPreparedAck(f.projectId,ack);await f.a.commitPreparedAck(f.projectId,ack);f.a=reopen(f.a,f.account);const row=(await f.a.listSyncConflictAlternatives(f.projectId))[0];expect(row.prepared.operation.targets).toHaveLength(operation.targets.length);expect(row.prepared.operation.targets.map(t=>t.targetId)).toEqual(expect.arrayContaining([f.idA,f.idB]));expect(row.prepared.operation).toEqual(operation);expect(await f.a.listSyncAckEvidence(f.projectId)).toHaveLength(1);await expect(f.a.commitPreparedAck(f.projectId,{...ack,serverRevision:'99'})).rejects.toMatchObject({code:'OPERATION_REUSED'});proof('R9V03',{row,unchangedB:true,duplicateEvidenceCount:1});});
it('R9V04 resolution approval rejects local revision changes and tampered candidate while retaining conflict/outbox',async()=>{const f=await conflict(),plan=await f.b.previewSyncResolution(f.projectId,f.row.operationId,{[f.idA]:{strategy:'server'}}),bad=structuredClone(plan);bad.candidate.name='偽承認';await expect(f.b.confirmSyncResolution(bad)).rejects.toMatchObject({code:'PROTOCOL_INVALID'});await edit(f.b,f.projectId,f.idB,'承認後の別入力');await expect(f.b.confirmSyncResolution(plan)).rejects.toMatchObject({code:'REVISION_CHANGED'});expect(await f.b.listPreparedConflicts(f.projectId)).toHaveLength(1);proof('R9V04',{oldRevision:plan.localRevision,newRevision:(await f.b.getProject(f.projectId))?.revision,conflictRetained:true});});
it('R9V05 remote update during resolution is not silently accepted: re-sent command conflicts and keeps original record',async()=>{const f=await conflict(),plan=await f.b.previewSyncResolution(f.projectId,f.row.operationId,{[f.idA]:{strategy:'local'}});await edit(f.a,f.projectId,f.idA,'解決中の遠隔新稿');await send(f.a,f);await f.b.confirmSyncResolution(plan);const result=await send(f.b,f);expect(result.ack.status).toBe('conflict');expect((await f.b.listSyncConflictAlternatives(f.projectId)).length).toBeGreaterThanOrEqual(2);proof('R9V05',{oldOperation:f.row.operationId,newOperation:result.operation.operationId,ack:result.ack});});
it('R9D04 protocol operation creation captures all target and scope input before hash awaits',async()=>{const f=input(),documents=nativeDocuments(f.p,'1'),base=documents.find(d=>d.id===f.idA)!,local=structuredClone(base);local.fields.name='今回のA';const later=structuredClone(documents.find(d=>d.id===f.idB)!);later.fields.name='今回のB';const options={scope:{accountId:f.account,projectId:f.p.projectId},operationId:newId(),baseRevision:'1',targets:[{base,local},{base:documents.find(d=>d.id===f.idB)!,local:later}]};const pending=createSyncOperation(options);later.fields.name='後発のB';options.scope.accountId=newId();const operation=await pending;proof('R9D04',{operation,originalAccount:f.account,callerLater:options});expect(operation.scope.accountId).toBe(f.account);expect(operation.targets.find(t=>t.targetId===f.idB)?.local.fields.name).toBe('今回のB');});
it('R9D05 public snapshot body parsing rejects responses after account-generation changes, including JSON await',async()=>{let release:((v:unknown)=>void)|undefined,calls=0;const client=new DedicatedSupabaseClient({url:'https://review.invalid/',publishableKey:'sb_publishable_independent_fixture'},async()=>{calls++;if(calls===1)return{ok:true,json:async()=>({access_token:'fixture-only-token',user:{id:input().account},expires_in:3600})}as Response;return{ok:true,json:()=>new Promise(resolve=>release=resolve)}as unknown as Response;});await client.signIn('review@example.invalid','fixture-password');const pending=client.publicSnapshots();await Promise.resolve();await Promise.resolve();client.expire();release?.([{id:newId(),projection:{publicTitle:'前アカウントの限定情報'},content_hash:'a'.repeat(64),expires_at:null}]);let refused=false,error='';try{await pending;}catch(e){refused=true;error=(e as Error).message;}proof('R9D05',{refused,error,session:client.getSession()});expect(refused).toBe(true);});
it('R9D06 concurrent identical ACKs are idempotent in native storage, both callers succeed without duplicate content/history/evidence',async()=>{const f=await seed();await edit(f.a,f.projectId,f.idA,'同一ACKの稿');const operation=(await f.a.prepareSavedOperations(f.projectId))!,ack=await f.server.send(operation,f.session),before=await f.a.getProject(f.projectId),results=await Promise.allSettled([f.a.commitPreparedAck(f.projectId,ack),f.a.commitPreparedAck(f.projectId,ack)]),after=await f.a.getProject(f.projectId);proof('R9D06',{results:results.map(x=>x.status==='fulfilled'?{status:x.status}:{status:x.status,error:String(x.reason),code:(x.reason as any).code}),beforeRevision:before?.revision,afterRevision:after?.revision,evidence:await f.a.listSyncAckEvidence(f.projectId),pending:await f.a.listOutbox(f.projectId)});expect(results.every(x=>x.status==='fulfilled')).toBe(true);expect(await f.a.listSyncAckEvidence(f.projectId)).toHaveLength(1);expect(await f.a.listOutbox(f.projectId)).toHaveLength(0);});
